package com.cloudmall.pay;
import com.cloudmall.common.api.ApiResponse;import com.cloudmall.common.error.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.util.*;import java.util.concurrent.*;
@RestController @RequestMapping("/api/payments")public class PayController{static final Map<String,Pay> DATA=new ConcurrentHashMap<>();static final Map<String,String> IDEM=new ConcurrentHashMap<>();
 @PostMapping public ApiResponse<?> create(@RequestHeader("Idempotency-Key")String key,@RequestBody Request r){if(r.orderNo==null||r.payAmount==null)throw new BizException(ErrorCodes.INVALID,"支付参数不完整",400);if(IDEM.containsKey(key))return ApiResponse.ok(DATA.get(IDEM.get(key)));Pay p=new Pay(UUID.randomUUID().toString(),r.orderNo,r.payAmount,"PENDING");DATA.put(p.payNo,p);IDEM.put(key,p.payNo);return ApiResponse.ok(p);}@GetMapping("/orders/{orderNo}")public ApiResponse<?> get(@PathVariable String orderNo){for(Pay p:DATA.values())if(p.orderNo.equals(orderNo))return ApiResponse.ok(p);throw new BizException(ErrorCodes.NOT_FOUND,"支付记录不存在",404);}
 @PostMapping("/{payNo}/mock-success")public ApiResponse<?> success(@PathVariable String payNo){Pay p=must(payNo);if("SUCCESS".equals(p.status))return ApiResponse.ok(p);if("CLOSED".equals(p.status))throw new BizException(ErrorCodes.PAY_DONE,"支付已关闭",409);p.status="SUCCESS";return ApiResponse.ok(p);}@PostMapping("/{payNo}/mock-fail")public ApiResponse<?> fail(@PathVariable String payNo){Pay p=must(payNo);if("SUCCESS".equals(p.status))throw new BizException(ErrorCodes.PAY_DONE,"支付已成功",409);p.status="FAILED";return ApiResponse.ok(p);}@PostMapping("/callback")public ApiResponse<?> callback(@RequestBody Callback c){Pay p=must(c.payNo);if("SUCCESS".equals(p.status))return ApiResponse.ok(p);p.status=c.success?"SUCCESS":"FAILED";return ApiResponse.ok(p);}
 private Pay must(String n){Pay p=DATA.get(n);if(p==null)throw new BizException(ErrorCodes.NOT_FOUND,"支付记录不存在",404);return p;}public static class Request{public String orderNo;public BigDecimal payAmount;}public static class Callback{public String payNo;public boolean success;}public static class Pay{public String payNo,orderNo,status;public BigDecimal amount;Pay(String p,String o,BigDecimal a,String s){payNo=p;orderNo=o;amount=a;status=s;}}
}
